import java.io.*;
import javax.servlet.http.*;

public class SecureServlet extends HttpServlet {
    public void doGet(HttpServletRequest request, HttpServletResponse response) {
        String input = request.getParameter("input");
        if (isValidInput(input)) { // Validate input before processing
            processUserInput(input);
        } else {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().write("Invalid input");
        }
    }

    private boolean isValidInput(String input) {
        return input != null && !input.matches("[^a-zA-Z0-9]+"); // Only allow alphanumeric characters
    }

    private void processUserInput(String input) {
        try {
            Runtime.getRuntime().exec(sanitizeInput(input)); // Sanitize input before using it
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private String sanitizeInput(String input) {
        return new String(input.getBytes("UTF-8"), "UTF-8"); // Basic sanitization example
    }
}
```

